from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

path='/root/gdp.xlsx'
wb=load_workbook(path, data_only=False)
ws=wb['Task']

for start_row in (12, 19, 26):
    for row in range(start_row, start_row + 6):
        for col in range(8, 13):
            year_cell=f'{get_column_letter(col)}$9'
            ws.cell(row, col).value=(
                f'=INDEX(Data!$H$21:$M$40,MATCH($D{row},Data!$B$21:$B$40,0),'
                f'MATCH({year_cell},Data!$H$4:$M$4,0))'
            )

for row in range(35, 41):
    source_row=row - 23
    for col in range(8, 13):
        col_letter=get_column_letter(col)
        ws.cell(row, col).value=f'=({col_letter}{source_row}-{col_letter}{source_row + 7})/{col_letter}{source_row + 14}*100'

stat_functions={42:'MIN', 43:'MAX', 44:'MEDIAN', 45:'AVERAGE', 46:'PERCENTILE.INC', 47:'PERCENTILE.INC'}
for row, function in stat_functions.items():
    for col in range(8, 13):
        letter=get_column_letter(col)
        range_ref=f'{letter}$35:{letter}$40'
        ws.cell(row, col).value=(f'={function}({range_ref})' if row < 46 else f'={function}({range_ref},{0.25 if row == 46 else 0.75})')

for col in range(8, 13):
    letter=get_column_letter(col)
    ws.cell(50, col).value=f'=SUMPRODUCT({letter}$35:{letter}$40,{letter}$26:{letter}$31)/SUM({letter}$26:{letter}$31)'

wb.calculation.fullCalcOnLoad = True
wb.calculation.forceFullCalc = True
wb.calculation.calcMode = 'auto'
wb.save(path)
